    var o = (((inA + outA - 180) / 2) % 360 + 360) % 360;
    var op = ((180 + 2 * o - inA) % 360 + 360) % 360;
    if (Math.abs(((op - outA + 540) % 360) - 180) > 0.5) { o = (o + 90) % 360; }
